create extension if not exists pgcrypto;
create type public.profile_status as enum ('active','suspended','deleted');
create type public.stock_status as enum ('available','low_stock','sold_out','unknown','discontinued');
create type public.confirmation_method as enum ('store_visit','staff_confirmation','phone','official_information');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique check(username is null or username ~ '^[a-z0-9_]{3,24}$'),created_at timestamptz not null default now(),status profile_status not null default 'active',posting_suspended boolean not null default false,is_admin boolean not null default false);
create table public.brands(id uuid primary key default gen_random_uuid(),name text not null,name_kana text,created_at timestamptz not null default now(),unique(name));
create table public.products(id uuid primary key default gen_random_uuid(),brand_id uuid not null references public.brands(id),name text not null,category text not null,jan_code text,created_at timestamptz not null default now(),is_active boolean not null default true,image_url text,unique(brand_id,name));
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,variant_name text not null,color_code text,jan_code text,created_at timestamptz not null default now(),unique(product_id,variant_name));
create table public.store_chains(id uuid primary key default gen_random_uuid(),name text not null unique,store_type text not null,created_at timestamptz not null default now(),is_active boolean not null default true);
create table public.stores(id uuid primary key default gen_random_uuid(),name text not null,chain_id uuid references public.store_chains(id),chain_name text,store_type text not null,address text not null,latitude double precision not null,longitude double precision not null,created_at timestamptz not null default now(),is_active boolean not null default true);
create table public.stock_reports(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id),product_variant_id uuid references public.product_variants(id),store_id uuid not null references public.stores(id),user_id uuid not null references public.profiles(id),status stock_status not null default 'available',confirmation_method confirmation_method not null,comment varchar(200),reported_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.product_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),payload jsonb not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.store_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),payload jsonb not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.abuse_reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),stock_report_id uuid references public.stock_reports(id),reason text not null,status text not null default 'open',created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce((select is_admin from public.profiles where id=auth.uid()),false) $$;
create index stock_reports_lookup on public.stock_reports(product_id,store_id,reported_at desc);
alter table public.profiles enable row level security;alter table public.brands enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.store_chains enable row level security;alter table public.stores enable row level security;alter table public.stock_reports enable row level security;alter table public.product_requests enable row level security;alter table public.store_requests enable row level security;alter table public.abuse_reports enable row level security;
create policy "public catalog brands" on public.brands for select using(true);create policy "public catalog products" on public.products for select using(is_active);create policy "public catalog variants" on public.product_variants for select using(true);create policy "public active chains" on public.store_chains for select using(is_active);create policy "public active stores" on public.stores for select using(is_active);
create policy "own profile" on public.profiles for select using(auth.uid()=id);create policy "insert own reports" on public.stock_reports for insert with check(auth.uid()=user_id and exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='active' and not p.posting_suspended));create policy "read own reports" on public.stock_reports for select using(auth.uid()=user_id);
create policy "own product requests" on public.product_requests for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own store requests" on public.store_requests for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own abuse reports" on public.abuse_reports for all using(auth.uid()=reporter_id) with check(auth.uid()=reporter_id);
create view public.public_stock_summaries with (security_invoker=false) as select sr.product_id,sr.store_id,max(sr.reported_at) as last_reported_at,array_agg(distinct pv.variant_name) filter(where pv.variant_name is not null) as confirmed_variants,count(*) as report_count from public.stock_reports sr left join public.product_variants pv on pv.id=sr.product_variant_id where sr.status='available' group by sr.product_id,sr.store_id;
revoke all on public.stock_reports from anon;grant select on public.public_stock_summaries to anon,authenticated;
create policy "admins read profiles" on public.profiles for select using(public.is_admin());
create policy "admins manage reports" on public.stock_reports for all using(public.is_admin());
create policy "admins manage chains" on public.store_chains for all using(public.is_admin()) with check(public.is_admin());
